import { Link } from "react-router-dom";
import { usePanier } from "../../hooks/usePanier";
import { useAuth } from "../../hooks/useAuth";

export default function BarreNavigation() {
  const { totalArticles } = usePanier();
  const { utilisateur, deconnecter } = useAuth();

  return (
    <nav style={{ backgroundColor: "#e44d26", padding: "14px 30px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
      <Link to="/" style={{ color: "white", fontSize: "22px", fontWeight: "bold" }}>🛍️ MonShop</Link>
      <div style={{ display: "flex", gap: "20px", alignItems: "center" }}>
        <Link to="/catalogue" style={{ color: "white" }}>Catalogue</Link>
        <Link to="/panier" style={{ color: "white" }}>🛒 ({totalArticles})</Link>
        {utilisateur ? (
          <>
            <Link to="/profil" style={{ color: "white" }}>{utilisateur.nom}</Link>
            <button onClick={deconnecter} style={{ background: "none", border: "1px solid white", color: "white", padding: "5px 10px", cursor: "pointer", borderRadius: "4px" }}>
              Déconnexion
            </button>
          </>
        ) : (
          <Link to="/connexion" style={{ color: "white" }}>Connexion</Link>
        )}
      </div>
    </nav>
  );
}
